#include <iostream>
#include <stdexcept>

double safeDivide(double num, double den) {
    if (den == 0.0) {
        // Proactively throw before division by zero takes place
        throw std::runtime_error("attempted to divide by zero");
    }
    return num / den;
}

int main() {
    double n = 100.0;
    double d = 0.0;

    try {
        std::cout << "Calculating division...\n";
        double result = safeDivide(n, d);
        std::cout << "The quotient is: " << result << "\n"; // skipped
    } catch (const std::runtime_error& ex) {
        std::cout << "Exception occurred: " << ex.what() << "\n";
    }

    std::cout << "Program execution safely resumes here.\n";
    return 0;
}

#include <iostream>
#include <stdexcept>

void processWorker() {
    try {
        std::cout << "  [Worker] Attempting task...\n";
        throw std::runtime_error("Worker encountered severe I/O failure");
    } catch (const std::exception&) {
        std::cout << "  [Worker] Caught exception locally; logging and rethrowing...\n";
        throw; // Rethrows the exact active exception
    }
}

int main() {
    std::cout << "[Main] Initiating worker...\n";
    try {
        processWorker();
        std::cout << "[Main] This line will never execute.\n";
    } catch (const std::runtime_error& err) {
        std::cout << "[Main] Caught rethrown exception: " << err.what() << "\n";
    }

    std::cout << "[Main] Execution completed cleanly.\n";
    return 0;
}
